@push('javascript')<script>    // Tab switching logic based on original logic found in style.blade or inline    // Injects an active class using cine-blue borders    function openCity(evt, cityName) {        var i, tabcontent, tablinks;        tabcontent = document.getElementsByClassName("tabcontent");        for (i = 0; i < tabcontent.length; i++) {            tabcontent[i].style.display = "none";        }        tablinks = document.getElementsByClassName("tablinks");        for (i = 0; i < tablinks.length; i++) {            tablinks[i].className = tablinks[i].className.replace(" border-cine-blue text-cine-navy", " text-cine-navy/60 border-transparent");            // Set base styles            if (!tablinks[i].className.includes("text-cine-navy/60")) {                 tablinks[i].className += " text-cine-navy/60 border-transparent";            }        }        document.getElementById(cityName).style.display = "block";        evt.currentTarget.className = evt.currentTarget.className.replace(" text-cine-navy/60 border-transparent", " border-cine-blue text-cine-navy");    }    // Explicitly click defaultOpen    document.addEventListener("DOMContentLoaded", function() {        var defaultTab = document.getElementById("defaultOpen");        if(defaultTab) {            defaultTab.click();        }    });</script>
@endpush
